1	/**
2	 * pdf-generator.ts
3	 *
4	 * Client-side PDF generation for ConvertScan audit reports.
5	 * Uses jsPDF + jspdf-autotable (both already installed).
6	 *
7	 * Dependencies: scan types, CRO_PILLARS config, score-utils
8	 */
9	
10	import jsPDF from "jspdf";
11	import autoTable from "jspdf-autotable";
12	import type { Scan, PillarResult, Finding, CopyRewrite } from "@/types";
13	import { CRO_PILLARS } from "@/lib/constants";
14	import {
15	  getScoreLabel,
16	  getScoreHex,
17	  getSeverityLabel,
18	  getEffortLabel,
19	  getIndustryBenchmark,
20	} from "@/lib/score-utils";
21	
22	// ── Brand colors ─────────────────────────────────────────────────
23	
24	const BRAND = {
25	  indigo: [99, 102, 241] as [number, number, number],
26	  indigoLight: [238, 240, 255] as [number, number, number],
27	  slate900: [15, 23, 42] as [number, number, number],
28	  slate700: [51, 65, 85] as [number, number, number],
29	  slate500: [100, 116, 139] as [number, number, number],
30	  slate200: [226, 232, 240] as [number, number, number],
31	  slate50: [248, 250, 252] as [number, number, number],
32	  white: [255, 255, 255] as [number, number, number],
33	  red: [239, 68, 68] as [number, number, number],
34	  amber: [245, 158, 11] as [number, number, number],
35	  green: [34, 197, 94] as [number, number, number],
36	  violet: [124, 58, 237] as [number, number, number],
37	};
38	
39	// ── Score color helper (returns RGB tuple) ────────────────────────
40	
41	function scoreRgb(score: number): [number, number, number] {
42	  if (score < 40) return BRAND.red;
43	  if (score < 70) return BRAND.amber;
44	  return BRAND.green;
45	}
46	
47	function severityRgb(severity: string): [number, number, number] {
48	  switch (severity) {
49	    case "critical": return BRAND.red;
50	    case "warning": return BRAND.amber;
51	    case "info": return [59, 130, 246];
52	    default: return BRAND.green;
53	  }
54	}
55	
56	// ── Layout constants ──────────────────────────────────────────────
57	
58	const MARGIN = 20;
59	const PAGE_W = 210;
60	const PAGE_H = 297;
61	const CONTENT_W = PAGE_W - MARGIN * 2;
62	
63	// ── Helpers ───────────────────────────────────────────────────────
64	
65	function addFooter(doc: jsPDF, pageNum: number, totalPages: number, dateStr: string): void {
66	  const y = PAGE_H - 10;
67	  doc.setFontSize(7.5);
68	  doc.setTextColor(...BRAND.slate500);
69	  doc.setFont("helvetica", "normal");
70	  doc.text("Generated by ConvertScan — convertscan.com", MARGIN, y);
71	  doc.text(`Page ${pageNum} of ${totalPages}`, PAGE_W / 2, y, { align: "center" });
72	  doc.text(dateStr, PAGE_W - MARGIN, y, { align: "right" });
73	
74	  // Footer rule
75	  doc.setDrawColor(...BRAND.slate200);
76	  doc.setLineWidth(0.3);
77	  doc.line(MARGIN, y - 3, PAGE_W - MARGIN, y - 3);
78	}
79	
80	function addPage(doc: jsPDF): void {
81	  doc.addPage();
82	}
83	
84	/** Returns wrapped lines and the new Y position after the text block */
85	function addWrappedText(
86	  doc: jsPDF,
87	  text: string,
88	  x: number,
89	  y: number,
90	  maxWidth: number,
91	  lineHeight: number,
92	): number {
93	  const lines = doc.splitTextToSize(text, maxWidth);
94	  doc.text(lines, x, y);
95	  return y + lines.length * lineHeight;
96	}
97	
98	/** Thin horizontal rule */
99	function rule(doc: jsPDF, y: number): void {
100	  doc.setDrawColor(...BRAND.slate200);
101	  doc.setLineWidth(0.3);
102	  doc.line(MARGIN, y, PAGE_W - MARGIN, y);
103	}
104	
105	/** Section heading with accent stripe */
106	function sectionHeading(doc: jsPDF, label: string, y: number): number {
107	  doc.setFillColor(...BRAND.indigo);
108	  doc.roundedRect(MARGIN, y, 3, 7, 1, 1, "F");
109	  doc.setFont("helvetica", "bold");
110	  doc.setFontSize(12);
111	  doc.setTextColor(...BRAND.slate900);
112	  doc.text(label, MARGIN + 7, y + 5.5);
113	  return y + 14;
114	}
115	
116	/** Colored score pill */
117	function scorePill(
118	  doc: jsPDF,
119	  score: number,
120	  cx: number,
121	  cy: number,
122	  radius = 12,
123	): void {
124	  const rgb = scoreRgb(score);
125	  doc.setFillColor(rgb[0], rgb[1], rgb[2]);
126	  doc.circle(cx, cy, radius, "F");
127	  doc.setTextColor(...BRAND.white);
128	  doc.setFont("helvetica", "bold");
129	  doc.setFontSize(score >= 100 ? 10 : 13);
130	  doc.text(`${Math.round(score)}`, cx, cy + 1.5, { align: "center", baseline: "middle" });
131	}
132	
133	// ── Page 1 — Cover ────────────────────────────────────────────────
134	
135	function buildCoverPage(
136	  doc: jsPDF,
137	  scan: Scan,
138	  profile: { full_name: string; company_name?: string },
139	  dateStr: string,
140	): void {
141	  // Top brand bar
142	  doc.setFillColor(...BRAND.indigo);
143	  doc.rect(0, 0, PAGE_W, 22, "F");
144	
145	  // Logo text
146	  doc.setTextColor(...BRAND.white);
147	  doc.setFont("helvetica", "bold");
148	  doc.setFontSize(16);
149	  doc.text("ConvertScan", MARGIN, 14);
150	
151	  // Report type badge (right of header bar)
152	  doc.setFontSize(8);
153	  doc.setTextColor(200, 201, 255);
154	  doc.text("CRO AUDIT REPORT", PAGE_W - MARGIN, 14, { align: "right" });
155	
156	  // ── Hero score area ─────────────────────────────────────────────
157	  const score = scan.overall_score ?? 0;
158	  const scoreLabel = getScoreLabel(score);
159	  const scoreHex = getScoreHex(score);
160	  const rgb = scoreRgb(score);
161	
162	  // Light bg block
163	  doc.setFillColor(...BRAND.slate50);
164	  doc.roundedRect(MARGIN, 32, CONTENT_W, 70, 3, 3, "F");
165	
166	  // Big score circle
167	  const cx = MARGIN + 38;
168	  const cy = 67;
169	  // Outer ring
170	  doc.setFillColor(rgb[0], rgb[1], rgb[2], 0.12);
171	  doc.setDrawColor(...rgb);
172	  doc.setLineWidth(2.5);
173	  doc.circle(cx, cy, 22, "S");
174	  // Inner fill
175	  doc.setFillColor(...rgb);
176	  doc.circle(cx, cy, 18, "F");
177	  // Score text
178	  doc.setTextColor(...BRAND.white);
179	  doc.setFont("helvetica", "bold");
180	  doc.setFontSize(20);
181	  doc.text(`${Math.round(score)}`, cx, cy + 1.5, { align: "center", baseline: "middle" });
182	  doc.setFontSize(8);
183	  doc.text("/100", cx, cy + 10, { align: "center" });
184	
185	  // Score label and URL
186	  doc.setFont("helvetica", "bold");
187	  doc.setFontSize(22);
188	  doc.setTextColor(...BRAND.slate900);
189	  doc.text(scoreLabel, MARGIN + 70, 54);
190	
191	  doc.setFont("helvetica", "normal");
192	  doc.setFontSize(9);
193	  doc.setTextColor(...BRAND.slate500);
194	  doc.text("Overall CRO Score", MARGIN + 70, 62);
195	
196	  // URL
197	  doc.setFontSize(9.5);
198	  doc.setTextColor(...BRAND.slate700);
199	  const urlText = scan.url.length > 68 ? scan.url.slice(0, 65) + "…" : scan.url;
200	  doc.text(urlText, MARGIN + 70, 75);
201	
202	  // Date
203	  doc.setFontSize(8.5);
204	  doc.setTextColor(...BRAND.slate500);
205	  doc.text(`Scanned: ${dateStr}`, MARGIN + 70, 85);
206	
207	  // ── Report title block ──────────────────────────────────────────
208	  doc.setFont("helvetica", "bold");
209	  doc.setFontSize(28);
210	  doc.setTextColor(...BRAND.slate900);
211	  doc.text("CRO Audit Report", MARGIN, 125);
212	
213	  doc.setFont("helvetica", "normal");
214	  doc.setFontSize(11);
215	  doc.setTextColor(...BRAND.slate500);
216	  const titleText = scan.page_title
217	    ? `${scan.page_title} — ${scan.page_type} page`
218	    : `${scan.page_type} page audit`;
219	  doc.text(titleText, MARGIN, 135);
220	
221	  // ── "Prepared for" block ────────────────────────────────────────
222	  const prepY = 155;
223	  doc.setFillColor(...BRAND.indigoLight);
224	  doc.roundedRect(MARGIN, prepY, CONTENT_W, 28, 3, 3, "F");
225	
226	  doc.setFont("helvetica", "bold");
227	  doc.setFontSize(9);
228	  doc.setTextColor(...BRAND.indigo);
229	  doc.text("PREPARED FOR", MARGIN + 8, prepY + 9);
230	
231	  doc.setFont("helvetica", "bold");
232	  doc.setFontSize(13);
233	  doc.setTextColor(...BRAND.slate900);
234	  doc.text(profile.company_name ?? profile.full_name, MARGIN + 8, prepY + 20);
235	
236	  if (profile.company_name) {
237	    doc.setFont("helvetica", "normal");
238	    doc.setFontSize(9);
239	    doc.setTextColor(...BRAND.slate500);
240	    doc.text(`Report recipient: ${profile.full_name}`, PAGE_W - MARGIN - 8, prepY + 20, { align: "right" });
241	  }
242	
243	  // Confidential stamp
244	  doc.setFont("helvetica", "bold");
245	  doc.setFontSize(7.5);
246	  doc.setTextColor(...BRAND.slate500);
247	  const confText = profile.company_name
248	    ? `CONFIDENTIAL — Prepared exclusively for ${profile.company_name}`
249	    : "CONFIDENTIAL — Not for redistribution";
250	  doc.text(confText, PAGE_W / 2, prepY + 36, { align: "center" });
251	
252	  // ── Key metrics preview strip ───────────────────────────────────
253	  const metricsY = 200;
254	  rule(doc, metricsY);
255	
256	  const metricItems = [
257	    { label: "Total Findings", value: scan.issues_found.toString() },
258	    { label: "Critical Issues", value: scan.critical_issues.toString() },
259	    { label: "Quick Wins", value: scan.quick_wins.toString() },
260	    { label: "Warnings", value: scan.warnings.toString() },
261	  ];
262	
263	  const colW = CONTENT_W / metricItems.length;
264	  metricItems.forEach(({ label, value }, i) => {
265	    const mx = MARGIN + i * colW + colW / 2;
266	    doc.setFont("helvetica", "bold");
267	    doc.setFontSize(20);
268	    doc.setTextColor(...BRAND.slate900);
269	    doc.text(value, mx, metricsY + 16, { align: "center" });
270	    doc.setFont("helvetica", "normal");
271	    doc.setFontSize(8);
272	    doc.setTextColor(...BRAND.slate500);
273	    doc.text(label, mx, metricsY + 23, { align: "center" });
274	  });
275	
276	  rule(doc, metricsY + 30);
277	
278	  // ── Score color legend ──────────────────────────────────────────
279	  const legendY = metricsY + 40;
280	  doc.setFont("helvetica", "normal");
281	  doc.setFontSize(8);
282	  doc.setTextColor(...BRAND.slate500);
283	  doc.text("Score Guide:", MARGIN, legendY);
284	
285	  const bands = [
286	    { label: "Excellent (85–100)", rgb: BRAND.green },
287	    { label: "Good (70–84)", rgb: BRAND.green },
288	    { label: "Average (55–69)", rgb: BRAND.amber },
289	    { label: "Below Average (40–54)", rgb: BRAND.amber },
290	    { label: "Poor (< 40)", rgb: BRAND.red },
291	  ];
292	
293	  let bandX = MARGIN + 26;
294	  bands.forEach(({ label, rgb: bRgb }) => {
295	    doc.setFillColor(...bRgb);
296	    doc.circle(bandX, legendY - 1.5, 2.5, "F");
297	    doc.setTextColor(...BRAND.slate700);
298	    doc.text(label, bandX + 4.5, legendY);
299	    bandX += 38;
300	  });
301	
302	  // ── Disclaimer note ─────────────────────────────────────────────
303	  doc.setFont("helvetica", "italic");
304	  doc.setFontSize(7.5);
305	  doc.setTextColor(...BRAND.slate500);
306	  doc.text(
307	    "This report reflects an AI-powered CRO analysis at the time of the scan. Results are advisory in nature.",
308	    PAGE_W / 2,
309	    260,
310	    { align: "center", maxWidth: CONTENT_W },
311	  );
312	}
313	
314	// ── Page 2 — Executive Summary ────────────────────────────────────
315	
316	function buildExecutiveSummary(
317	  doc: jsPDF,
318	  scan: Scan,
319	  pillarResults: PillarResult[],
320	  dateStr: string,
321	): void {
322	  addPage(doc);
323	
324	  let y = MARGIN + 5;
325	  doc.setFillColor(...BRAND.indigo);
326	  doc.rect(0, 0, PAGE_W, 10, "F");
327	  doc.setTextColor(...BRAND.white);
328	  doc.setFont("helvetica", "bold");
329	  doc.setFontSize(8);
330	  doc.text("ConvertScan CRO Audit Report", MARGIN, 7);
331	  doc.text("Executive Summary", PAGE_W - MARGIN, 7, { align: "right" });
332	  y = 22;
333	
334	  y = sectionHeading(doc, "Executive Summary", y);
335	
336	  // Score overview row
337	  const score = scan.overall_score ?? 0;
338	  const rgb = scoreRgb(score);
339	
340	  doc.setFillColor(...BRAND.slate50);
341	  doc.roundedRect(MARGIN, y, CONTENT_W, 30, 2, 2, "F");
342	
343	  // Score pill
344	  scorePill(doc, score, MARGIN + 22, y + 15, 11);
345	
346	  // Label + sublabel
347	  doc.setFont("helvetica", "bold");
348	  doc.setFontSize(14);
349	  doc.setTextColor(...BRAND.slate900);
350	  doc.text(`${Math.round(score)}/100 — ${getScoreLabel(score)}`, MARGIN + 40, y + 11);
351	
352	  doc.setFont("helvetica", "normal");
353	  doc.setFontSize(8.5);
354	  doc.setTextColor(...BRAND.slate500);
355	  doc.text(
356	    `${scan.url} · ${dateStr} · ${scan.page_type} page`,
357	    MARGIN + 40,
358	    y + 20,
359	    { maxWidth: CONTENT_W - 45 },
360	  );
361	
362	  y += 38;
363	
364	  // ── Pillar scores table ─────────────────────────────────────────
365	  const pillarRows = pillarResults.map((pr) => {
366	    const cfg = CRO_PILLARS.find((c) => c.key === pr.pillar);
367	    const benchmark = getIndustryBenchmark(pr.pillar);
368	    const diff = pr.score - benchmark;
369	    const diffLabel = diff >= 0 ? `+${diff} vs avg` : `${diff} vs avg`;
370	    return [
371	      cfg?.label ?? pr.pillar,
372	      `${Math.round(pr.score)}/100`,
373	      getScoreLabel(pr.score),
374	      `${Math.round(pr.weight * 100)}%`,
375	      `${benchmark}/100`,
376	      diffLabel,
377	    ];
378	  });
379	
380	  autoTable(doc, {
381	    startY: y,
382	    head: [["Pillar", "Score", "Status", "Weight", "Industry Avg", "vs Avg"]],
383	    body: pillarRows,
384	    theme: "grid",
385	    styles: { font: "helvetica", fontSize: 8.5, cellPadding: 3.5 },
386	    headStyles: {
387	      fillColor: BRAND.indigo,
388	      textColor: BRAND.white,
389	      fontStyle: "bold",
390	      fontSize: 8.5,
391	    },
392	    columnStyles: {
393	      0: { cellWidth: 45 },
394	      1: { cellWidth: 22, halign: "center" },
395	      2: { cellWidth: 30 },
396	      3: { cellWidth: 18, halign: "center" },
397	      4: { cellWidth: 26, halign: "center" },
398	      5: { cellWidth: 24, halign: "center" },
399	    },
400	    didParseCell: (data) => {
401	      if (data.section === "body" && data.column.index === 1) {
402	        const scoreVal = pillarResults[data.row.index]?.score ?? 0;
403	        const cellRgb = scoreRgb(scoreVal);
404	        data.cell.styles.textColor = cellRgb;
405	        data.cell.styles.fontStyle = "bold";
406	      }
407	      if (data.section === "body" && data.column.index === 5) {
408	        const pillar = pillarResults[data.row.index];
409	        if (pillar) {
410	          const diff = pillar.score - getIndustryBenchmark(pillar.pillar);
411	          data.cell.styles.textColor = diff >= 0 ? BRAND.green : BRAND.red;
412	          data.cell.styles.fontStyle = "bold";
413	        }
414	      }
415	    },
416	    alternateRowStyles: { fillColor: BRAND.slate50 },
417	    margin: { left: MARGIN, right: MARGIN },
418	  });
419	
420	  const finalY = (doc as jsPDF & { lastAutoTable: { finalY: number } }).lastAutoTable.finalY;
421	  y = finalY + 14;
422	
423	  if (y > 230) {
424	    addPage(doc);
425	    y = MARGIN + 15;
426	  }
427	
428	  // ── Top 3 Priority Fixes ────────────────────────────────────────
429	  y = sectionHeading(doc, "Top 3 Priority Fixes", y);
430	
431	  const allFindings = pillarResults.flatMap((pr) => pr.findings);
432	  const topFixes = allFindings
433	    .filter((f) => f.severity === "critical")
434	    .slice(0, 3);
435	
436	  if (topFixes.length === 0) {
437	    doc.setFont("helvetica", "italic");
438	    doc.setFontSize(9);
439	    doc.setTextColor(...BRAND.slate500);
440	    doc.text("No critical issues found — great work!", MARGIN, y);
441	    y += 12;
442	  } else {
443	    topFixes.forEach((finding, idx) => {
444	      if (y > 255) {
445	        addPage(doc);
446	        y = MARGIN + 15;
447	      }
448	      const blockH = 28;
449	      doc.setFillColor(...BRAND.slate50);
450	      doc.roundedRect(MARGIN, y, CONTENT_W, blockH, 2, 2, "F");
451	
452	      // Number badge
453	      doc.setFillColor(...BRAND.red);
454	      doc.circle(MARGIN + 7, y + blockH / 2, 5.5, "F");
455	      doc.setTextColor(...BRAND.white);
456	      doc.setFont("helvetica", "bold");
457	      doc.setFontSize(8);
458	      doc.text(`${idx + 1}`, MARGIN + 7, y + blockH / 2 + 0.5, { align: "center", baseline: "middle" });
459	
460	      // Title
461	      doc.setFont("helvetica", "bold");
462	      doc.setFontSize(9.5);
463	      doc.setTextColor(...BRAND.slate900);
464	      doc.text(finding.title, MARGIN + 16, y + 9);
465	
466	      // Recommendation preview
467	      doc.setFont("helvetica", "normal");
468	      doc.setFontSize(8);
469	      doc.setTextColor(...BRAND.slate500);
470	      const recText = finding.recommendation.length > 120
471	        ? finding.recommendation.slice(0, 117) + "…"
472	        : finding.recommendation;
473	      doc.text(recText, MARGIN + 16, y + 18, { maxWidth: CONTENT_W - 22 });
474	
475	      // Lift badge
476	      if (finding.estimated_lift) {
477	        doc.setFont("helvetica", "bold");
478	        doc.setFontSize(7.5);
479	        doc.setTextColor(...BRAND.violet);
480	        doc.text(`Est. lift: ${finding.estimated_lift}`, PAGE_W - MARGIN - 4, y + 9, { align: "right" });
481	      }
482	
483	      y += blockH + 5;
484	    });
485	  }
486	}
487	
488	// ── Pages 3+ — Pillar Breakdown ───────────────────────────────────
489	
490	function buildPillarPages(
491	  doc: jsPDF,
492	  pillarResults: PillarResult[],
493	): void {
494	  const sortedPillars = [...pillarResults].sort((a, b) => a.score - b.score);
495	
496	  sortedPillars.forEach((pillar) => {
497	    addPage(doc);
498	
499	    let y = 10;
500	
501	    // Header bar
502	    const rgb = scoreRgb(pillar.score);
503	    doc.setFillColor(...rgb);
504	    doc.rect(0, 0, PAGE_W, 12, "F");
505	    doc.setTextColor(...BRAND.white);
506	    doc.setFont("helvetica", "bold");
507	    doc.setFontSize(9);
508	    const cfg = CRO_PILLARS.find((c) => c.key === pillar.pillar);
509	    const pillarLabel = cfg?.label ?? pillar.pillar;
510	    doc.text(`ConvertScan · ${pillarLabel}`, MARGIN, 8.5);
511	    doc.text(`Score: ${Math.round(pillar.score)}/100`, PAGE_W - MARGIN, 8.5, { align: "right" });
512	
513	    y = 22;
514	
515	    // Pillar title block
516	    doc.setFont("helvetica", "bold");
517	    doc.setFontSize(16);
518	    doc.setTextColor(...BRAND.slate900);
519	    doc.text(pillarLabel, MARGIN, y + 7);
520	
521	    // Score pill beside title
522	    scorePill(doc, pillar.score, PAGE_W - MARGIN - 16, y + 3, 10);
523	
524	    y += 16;
525	
526	    // Benchmark comparison bar
527	    const benchmark = getIndustryBenchmark(pillar.pillar);
528	    doc.setFontSize(8);
529	    doc.setFont("helvetica", "normal");
530	    doc.setTextColor(...BRAND.slate500);
531	    doc.text(`Industry average: ${benchmark}/100`, MARGIN, y + 5);
532	    const diff = pillar.score - benchmark;
533	    const diffLabel = diff >= 0 ? `${diff} points above average` : `${Math.abs(diff)} points below average`;
534	    doc.setTextColor(diff >= 0 ? BRAND.green[0] : BRAND.red[0], diff >= 0 ? BRAND.green[1] : BRAND.red[1], diff >= 0 ? BRAND.green[2] : BRAND.red[2]);
535	    doc.setFont("helvetica", "bold");
536	    doc.text(diffLabel, MARGIN + 60, y + 5);
537	
538	    y += 12;
539	
540	    // Visual score bar
541	    const barW = CONTENT_W * 0.7;
542	    doc.setFillColor(...BRAND.slate200);
543	    doc.roundedRect(MARGIN, y, barW, 5, 2, 2, "F");
544	    const filledW = (pillar.score / 100) * barW;
545	    doc.setFillColor(...rgb);
546	    doc.roundedRect(MARGIN, y, filledW, 5, 2, 2, "F");
547	    // Benchmark marker
548	    const markerX = MARGIN + (benchmark / 100) * barW;
549	    doc.setFillColor(...BRAND.slate700);
550	    doc.rect(markerX - 0.5, y - 1, 1, 7, "F");
551	
552	    y += 14;
553	    rule(doc, y);
554	    y += 8;
555	
556	    // ── Findings ──────────────────────────────────────────────────
557	    const findings = pillar.findings.filter((f) => f.severity !== "passed");
558	
559	    if (findings.length === 0) {
560	      doc.setFont("helvetica", "italic");
561	      doc.setFontSize(9);
562	      doc.setTextColor(...BRAND.slate500);
563	      doc.text("No issues found for this pillar.", MARGIN, y + 6);
564	      return;
565	    }
566	
567	    findings.forEach((finding) => {
568	      // Height estimate: title(10) + current(20) + rec(20) + ai(20) + meta(10) + pad = ~88
569	      const neededH = estimateFindingHeight(finding);
570	      if (y + neededH > 270) {
571	        addPage(doc);
572	        y = MARGIN + 5;
573	        // Mini header on continuation page
574	        doc.setFillColor(...rgb);
575	        doc.rect(0, 0, PAGE_W, 8, "F");
576	        doc.setTextColor(...BRAND.white);
577	        doc.setFont("helvetica", "bold");
578	        doc.setFontSize(7.5);
579	        doc.text(`ConvertScan · ${pillarLabel} (continued)`, MARGIN, 6);
580	        y = 16;
581	      }
582	
583	      y = renderFinding(doc, finding, y);
584	      y += 6;
585	    });
586	  });
