1	/**
2	 * public-report — Edge Function
3	 *
4	 * Serves a public CRO audit report for a given share token.
5	 * No auth required. Uses service_role to bypass RLS.
6	 *
7	 * GET ?token=<share_token>
8	 *
9	 * Returns:
10	 *   { scan: SanitizedScan, results: ScanResultRow[] }
11	 *
12	 * Required env vars:
13	 *   SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
14	 */
15	
16	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
17	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
18	
19	// ── CORS headers ──────────────────────────────────────────────
20	
21	const corsHeaders = {
22	  "Access-Control-Allow-Origin": "*",
23	  "Access-Control-Allow-Headers":
24	    "authorization, x-client-info, apikey, content-type",
25	  "Access-Control-Allow-Methods": "GET, OPTIONS",
26	};
27	
28	function corsResponse(body: unknown, status = 200) {
29	  return new Response(JSON.stringify(body), {
30	    status,
31	    headers: { ...corsHeaders, "Content-Type": "application/json" },
32	  });
33	}
34	
35	// ── DB row shapes (local — no shared imports in edge functions) ─
36	
37	interface ScanRow {
38	  id: string;
39	  user_id: string;
40	  url: string;
41	  favicon_url: string | null;
42	  page_title: string | null;
43	  page_type: string;
44	  status: string;
45	  overall_score: number | null;
46	  issues_found: number;
47	  critical_issues: number;
48	  warnings: number;
49	  quick_wins: number;
50	  screenshot_url: string | null;
51	  device: string;
52	  share_token: string | null;
53	  is_public: boolean;
54	  created_at: string;
55	  completed_at: string | null;
56	}
57	
58	interface DbFinding {
59	  id: string;
60	  title: string;
61	  severity: string;
62	  current_state: string;
63	  recommendation: string;
64	  ai_suggestion: string;
65	  is_premium: boolean;
66	  effort: string;
67	  estimated_lift: string;
68	  category: string;
69	}
70	
71	interface ScanResultRow {
72	  id: string;
73	  scan_id: string;
74	  pillar: string;
75	  score: number;
76	  weight: number;
77	  benchmark: number;
78	  findings: DbFinding[];
79	  fixed_findings: string[];
80	  created_at: string;
81	}
82	
83	// Sanitize scan: remove user_id, keep only public-safe fields
84	type SanitizedScan = Omit<ScanRow, "user_id">;
85	
86	function sanitizeScan(row: ScanRow): SanitizedScan {
87	  const { user_id: _removed, ...rest } = row;
88	  return rest;
89	}
90	
91	// Filter findings: remove premium ones if the scan was on a free plan
92	// Since we don't know the plan here, we expose all non-premium findings
93	// Premium findings have ai_suggestion blurred on the client side anyway
94	function sanitizeResults(results: ScanResultRow[]): ScanResultRow[] {
95	  return results.map((r) => ({
96	    ...r,
97	    findings: r.findings.filter((f) => !f.is_premium),
98	  }));
99	}
100	
101	// ── Handler ───────────────────────────────────────────────────
102	
103	serve(async (req: Request) => {
104	  // Preflight
105	  if (req.method === "OPTIONS") {
106	    return new Response(null, { headers: corsHeaders });
107	  }
108	
109	  if (req.method !== "GET") {
110	    return corsResponse({ error: "Method not allowed" }, 405);
111	  }
112	
113	  const url = new URL(req.url);
114	  const token = url.searchParams.get("token");
115	
116	  if (!token || token.trim() === "") {
117	    return corsResponse({ error: "Missing token" }, 400);
118	  }
119	
120	  const supabaseUrl = Deno.env.get("SUPABASE_URL");
121	  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
122	
123	  if (!supabaseUrl || !serviceKey) {
124	    return corsResponse({ error: "Server configuration error" }, 500);
125	  }
126	
127	  // Use service_role client to bypass RLS
128	  const adminClient = createClient(supabaseUrl, serviceKey, {
129	    auth: { persistSession: false },
130	  });
131	
132	  // Fetch scan by share_token
133	  const { data: scanData, error: scanError } = await adminClient
134	    .from("scans")
135	    .select("*")
136	    .eq("share_token", token)
137	    .eq("is_public", true)
138	    .maybeSingle();
139	
140	  if (scanError) {
141	    return corsResponse({ error: "Database error" }, 500);
142	  }
143	
144	  if (!scanData) {
145	    return corsResponse({ error: "Report not found or no longer public" }, 404);
146	  }
147	
148	  const scan = scanData as ScanRow;
149	
150	  // Fetch scan results
151	  const { data: resultsData, error: resultsError } = await adminClient
152	    .from("scan_results")
153	    .select("*")
154	    .eq("scan_id", scan.id);
155	
156	  if (resultsError) {
157	    return corsResponse({ error: "Failed to load report results" }, 500);
158	  }
159	
160	  const results = (resultsData ?? []) as ScanResultRow[];
161	
162	  return corsResponse({
163	    scan: sanitizeScan(scan),
164	    results: sanitizeResults(results),
165	  });
166	});
