20	// ── useGenerateShareLink ────────────────────────────────────────
21	
22	export function useGenerateShareLink() {
23	  const queryClient = useQueryClient();
24	
25	  return useMutation({
26	    mutationFn: async (scanId: string): Promise<string> => {
27	      const token = crypto.randomUUID();
28	      const { error } = await supabase
29	        .from("scans")
30	        .update({ share_token: token, is_public: true })
31	        .eq("id", scanId);
32	
33	      if (error) throw new Error(error.message);
34	
35	      return `${window.location.origin}/r/${token}`;
36	    },
37	    onSuccess: (_url, scanId) => {
38	      // Invalidate so useScan refetches updated share_token + is_public
39	      queryClient.invalidateQueries({ queryKey: ["scans", scanId] });
40	      queryClient.invalidateQueries({ queryKey: ["scans"] });
41	    },
42	  });
43	}
44	
45	// ── useRevokeShareLink ──────────────────────────────────────────
46	
47	export function useRevokeShareLink() {
48	  const queryClient = useQueryClient();
49	
50	  return useMutation({
51	    mutationFn: async (scanId: string): Promise<void> => {
52	      const { error } = await supabase
53	        .from("scans")
54	        .update({ share_token: null, is_public: false })
55	        .eq("id", scanId);
56	
57	      if (error) throw new Error(error.message);
58	    },
59	    onSuccess: (_data, scanId) => {
60	      queryClient.invalidateQueries({ queryKey: ["scans", scanId] });
61	      queryClient.invalidateQueries({ queryKey: ["scans"] });
62	    },
63	  });
64	}
