95	export function usePublicScan(token: string) {
96	  return useQuery({
97	    queryKey: shareReportKeys.publicScan(token),
98	    queryFn: async (): Promise<PublicScanPayload> => {
99	      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
100	      const supabaseKey = (
101	        (import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string | undefined) ??
102	        (import.meta.env.VITE_SUPABASE_ANON_KEY as string | undefined)
103	      );
104	
105	      if (!supabaseUrl || !supabaseKey) {
106	        throw new Error("Missing Supabase environment variables");
107	      }
108	
109	      const res = await fetch(
110	        `${supabaseUrl}/functions/v1/public-report?token=${encodeURIComponent(token)}`,
111	        {
112	          headers: {
113	            apikey: supabaseKey,
114	            "Content-Type": "application/json",
115	          },
116	        }
117	      );
118	
119	      if (res.status === 404) {
120	        throw new Error("NOT_FOUND");
121	      }
122	
123	      if (!res.ok) {
124	        throw new Error(`Failed to load public report: ${res.status}`);
125	      }
126	
127	      const json = (await res.json()) as {
128	        scan: Omit<Scan, "user_id">;
129	        results: ScanResultRow[];
130	      };
131	
132	      return {
133	        scan: json.scan,
134	        results: json.results.map(rowToPillarResult),
135	      };
136	    },
137	    enabled: !!token,
138	    staleTime: 1000 * 60 * 5,
139	    retry: (failureCount, error) => {
140	      if (error instanceof Error && error.message === "NOT_FOUND") return false;
141	      return failureCount < 2;
142	    },
143	  });
144	}
