function buildEnhancedDetailedFindings(
  doc: jsPDF,
  pillarResults: PillarResult[],
  accent: [number, number, number],
): void {
  const sorted = [...pillarResults].sort((a, b) => a.score - b.score);

  sorted.forEach((pr) => {
    const actionableFindings = pr.findings.filter((f) => f.severity !== "passed");
    if (actionableFindings.length === 0) return;

    doc.addPage();
    const rgb = scoreRgb(pr.score);
    enhancedPageHeader(doc, rgb, "ConvertScan · Detailed Findings", `${CRO_PILLARS.find((c) => c.key === pr.pillar)?.label ?? pr.pillar}`);

    let y = 18;
    const pillarLabel = CRO_PILLARS.find((c) => c.key === pr.pillar)?.label ?? pr.pillar;
    y = sectionHeading(doc, `${pillarLabel} — Score: ${Math.round(pr.score)}/100`, y);

    // Sort findings: critical first
    const sortedFindings = [...actionableFindings].sort((a, b) => {
      const order: Record<string, number> = { critical: 0, warning: 1, info: 2 };
      return (order[a.severity] ?? 3) - (order[b.severity] ?? 3);
    });

    sortedFindings.forEach((finding) => {
      const neededH = estimateFindingHeight(finding);
      if (y + neededH > 272) {
        doc.addPage();
        enhancedPageHeader(doc, rgb, "ConvertScan · Detailed Findings", `${pillarLabel} (continued)`);

